from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable


@dataclass(frozen=True)
class TrustRuleDefinition:
    rule_id: str
    dimension: str
    title: str
    severity: str
    weight: int
    match_key: str
    match_value: str
    plain_language: str
    user_question: str
    recommended_action: str
    quiet_copy: str
    report_copy: str
    evidence_prompt: str
    reduces_pressure: bool = True


@dataclass(frozen=True)
class EvidenceCompressionPattern:
    pattern_id: str
    relation: str
    bucket: str
    priority: int
    label: str
    summary_template: str
    reviewer_question: str
    missing_prompt: str
    support_copy: str
    caution_copy: str
    quiet_copy: str
    report_copy: str


@dataclass(frozen=True)
class DecisionImpactDefinition:
    impact_id: str
    action: str
    title: str
    tone: str
    summary_template: str
    recall_effect: str
    graph_effect: str
    open_loop_effect: str
    user_pressure: str
    warnings: tuple[str, ...]
    confirmation_question: str
    next_step: str


@dataclass(frozen=True)
class ReviewPathTemplate:
    template_id: str
    stage: str
    label: str
    trigger: str
    instruction: str
    evidence_hint: str
    completion_signal: str
    fallback_action: str
    quiet_copy: str
    metric_key: str


@dataclass(frozen=True)
class ReportSectionDefinition:
    section_id: str
    title: str
    priority: int
    trigger: str
    summary_template: str
    empty_template: str
    metric_key: str
    detail_prompt: str
    quiet_copy: str
    action_label: str


@dataclass(frozen=True)
class SessionModeDefinition:
    mode_id: str
    label: str
    intent: str
    ordering: tuple[str, ...]
    include_risks: tuple[str, ...]
    include_statuses: tuple[str, ...]
    empty_copy: str
    next_step_copy: str
    quiet_rule: str
    completion_copy: str


@dataclass(frozen=True)
class PressureGuardrailDefinition:
    guardrail_id: str
    surface: str
    trigger: str
    max_items: int
    collapsed_label: str
    expansion_label: str
    reason: str
    fallback: str


