def rules_for_dimension(dimension: str) -> list[TrustRuleDefinition]:
    return [rule for rule in TRUST_RULE_DEFINITIONS if rule.dimension == dimension]


def rules_for_match(match_key: str, match_value: str) -> list[TrustRuleDefinition]:
    return [
        rule for rule in TRUST_RULE_DEFINITIONS
        if rule.match_key == match_key and rule.match_value == match_value
    ]


def evidence_patterns_for_relation(relation: str) -> list[EvidenceCompressionPattern]:
    matches = [pattern for pattern in EVIDENCE_COMPRESSION_PATTERNS if pattern.relation == relation]
    return sorted(matches, key=lambda pattern: pattern.priority)


def evidence_patterns_for_bucket(bucket: str) -> list[EvidenceCompressionPattern]:
    matches = [pattern for pattern in EVIDENCE_COMPRESSION_PATTERNS if pattern.bucket == bucket]
    return sorted(matches, key=lambda pattern: pattern.priority)


def decision_impacts_for_action(action: str) -> list[DecisionImpactDefinition]:
    return [impact for impact in DECISION_IMPACT_DEFINITIONS if impact.action == action]


def first_decision_impact(action: str) -> DecisionImpactDefinition:
    matches = decision_impacts_for_action(action)
    if matches:
        return matches[0]
    return DECISION_IMPACT_DEFINITIONS[0]


def review_path_templates_for_stage(stage: str) -> list[ReviewPathTemplate]:
    return [template for template in REVIEW_PATH_TEMPLATES if template.stage == stage]


def report_sections_for_trigger(trigger: str) -> list[ReportSectionDefinition]:
    return [section for section in REPORT_SECTION_DEFINITIONS if section.trigger == trigger]


def report_sections_by_priority(limit: int = 8) -> list[ReportSectionDefinition]:
    return sorted(REPORT_SECTION_DEFINITIONS, key=lambda section: (section.priority, section.section_id))[:limit]


def session_mode_definition(mode_id: str) -> SessionModeDefinition:
    for mode in SESSION_MODE_DEFINITIONS:
        if mode.mode_id == mode_id:
            return mode
    return SESSION_MODE_DEFINITIONS[0]


def pressure_guardrails_for_surface(surface: str) -> list[PressureGuardrailDefinition]:
    return [guardrail for guardrail in PRESSURE_GUARDRAIL_DEFINITIONS if guardrail.surface == surface]


def pressure_guardrails_for_surfaces(surfaces: Iterable[str]) -> list[PressureGuardrailDefinition]:
    wanted = set(surfaces)
    return [guardrail for guardrail in PRESSURE_GUARDRAIL_DEFINITIONS if guardrail.surface in wanted]
